.ch-conclusion-scope {
  --ink: #0F172A;
  --muted: #64748B;
  --accent: #06B6D4;
  --warm: #D97706;
  --line: #E2E8F0;
  --paper: #F8FAFC;
  --danger: #EF4444;
  --success: #10B981;

  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  line-height: 1.6;
  padding: 2rem;
  box-sizing: border-box;
  max-width: 100%;
  overflow-x: hidden;
}

.ch-conclusion-scope * {
  box-sizing: border-box;
}

.chapter-section {
  margin-bottom: 3rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 2rem;
}

.chapter-section:last-child {
  border-bottom: none;
}

.section-header {
  margin-bottom: 1.5rem;
}

.section-title {
  font-size: 1.5rem;
  color: var(--ink);
  margin: 0 0 0.5rem 0;
  border-left: 4px solid var(--accent);
  padding-left: 1rem;
}

.section-lead {
  font-size: 1rem;
  color: var(--muted);
  margin: 0;
  max-width: 700px;
}

.trilemma-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2rem;
}

.prop-card {
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.25rem;
  border-radius: 6px;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  position: relative;
}

.prop-badge {
  font-weight: bold;
  color: var(--accent);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.prop-statement {
  font-size: 1rem;
  color: var(--ink);
  margin: 0;
  flex-grow: 1;
}

.prop-symbol {
  font-family: 'Times New Roman', serif;
  font-style: italic;
  color: var(--muted);
  font-size: 0.9rem;
  background: var(--paper);
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  align-self: flex-start;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.8rem;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
  cursor: pointer;
  align-self: flex-start;
  transition: all 0.2s;
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.logic-connector {
  margin: 2rem 0;
  text-align: center;
}

.connector-svg {
  max-width: 100%;
  height: auto;
}

.workbench-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  background: #fff;
  border: 1px solid var(--line);
  padding: 1.5rem;
  border-radius: 8px;
  margin-bottom: 2rem;
}

@media (max-width: 768px) {
  .workbench-container {
    grid-template-columns: 1fr;
  }
}

.control-panel h3 {
  margin-top: 0;
  font-size: 1.1rem;
  color: var(--ink);
}

.instruction {
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.input-group label {
  font-size: 0.9rem;
  font-weight: bold;
  color: var(--ink);
}

.input-group input {
  padding: 0.6rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 1rem;
  color: var(--ink);
  background: var(--paper);
}

.button-row {
  display: flex;
  gap: 0.5rem;
}

.action-btn {
  padding: 0.6rem 1rem;
  background: var(--ink);
  color: #fff;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.9rem;
  flex: 1;
  transition: opacity 0.2s;
}

.action-btn.secondary {
  background: transparent;
  border: 1px solid var(--line);
  color: var(--ink);
}

.action-btn:hover {
  opacity: 0.9;
}

.feedback-msg {
  margin-top: 1rem;
  font-size: 0.9rem;
  min-height: 1.5rem;
  color: var(--muted);
  padding: 0.5rem;
  border-radius: 4px;
  background: var(--paper);
}

.feedback-msg.error {
  color: var(--danger);
  background: #FEF2F2;
}

.feedback-msg.success {
  color: var(--success);
  background: #F0FDF4;
}

.status-display {
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 1px solid var(--line);
}

.status-item {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  font-size: 0.9rem;
}

.status-label {
  color: var(--muted);
}

.status-value {
  font-weight: bold;
  color: var(--ink);
}

.visual-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.pie-chart-wrapper {
  width: 220px;
  height: 220px;
  position: relative;
}

.credence-pie {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.pie-slice {
  stroke: #fff;
  stroke-width: 2;
  transition: d 0.5s ease;
}

.pie-center-text {
  transform: rotate(90deg);
  font-weight: bold;
}

.legend {
  margin-top: 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  font-size: 0.85rem;
  width: 100%;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.dot {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.conclusion-box {
  background: var(--ink);
  color: #fff;
  padding: 2rem;
  border-radius: 8px;
  text-align: center;
  border: 2px solid var(--accent);
  margin-top: 2rem;
}

.conclusion-box.hidden {
  display: none;
}

.conclusion-box h3 {
  margin-top: 0;
  color: var(--accent);
  font-size: 1.2rem;
}

.conclusion-text {
  font-family: serif;
  font-style: italic;
  font-size: 1.1rem;
  margin: 1.5rem 0;
  line-height: 1.5;
}

.conclusion-cn {
  font-size: 1rem;
  color: var(--accent);
  margin-bottom: 1.5rem;
  font-weight: bold;
}

.source-row {
  display: flex;
  justify-content: center;
  gap: 1rem;
}

.conclusion-box .source-btn {
  border-color: var(--accent);
  color: var(--accent);
}

@media (prefers-reduced-motion: reduce) {
  .pie-slice {
    transition: none;
  }
  .action-btn {
    transition: none;
  }
}

@media (max-width: 480px) {
  .ch-conclusion-scope {
    padding: 1rem;
  }
  .section-title {
    font-size: 1.25rem;
  }
  .prop-card {
    padding: 1rem;
  }
  .workbench-container {
    padding: 1rem;
  }
  .pie-chart-wrapper {
    width: 180px;
    height: 180px;
  }
}
