(function() {
  const scope = document.querySelector('.ch-conclusion-scope');
  if (!scope) return;

  // State
  let credence = { p1: 0.333, p2: 0.333, p3: 0.334 };
  let isBalanced = true;
  let excludedProps = [];

  // Elements
  const inputEl = scope.querySelector('#credence-input');
  const applyBtn = scope.querySelector('#apply-info-btn');
  const resetBtn = scope.querySelector('#reset-credence-btn');
  const feedbackEl = scope.querySelector('#feedback-msg');
  const conclusionBox = scope.querySelector('#final-conclusion');
  const slicesGroup = scope.querySelector('#pie-slices');
  const statusText = scope.querySelector('#status-text');
  const logicResult = scope.querySelector('#logic-result');

  // Source Buttons
  scope.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      const sourceId = btn.getAttribute('data-source');
      if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sourceId]) {
        const source = window.paperMindData.sources[sourceId];
        feedbackEl.textContent = `已定位来源：p.${source.page} - "${source.quote.substring(0, 40)}..."`;
        feedbackEl.className = 'feedback-msg success';
        feedbackEl.setAttribute('data-value', 'source-found');
      } else {
        feedbackEl.textContent = `来源 ${sourceId} 暂未加载`;
        feedbackEl.className = 'feedback-msg error';
        feedbackEl.setAttribute('data-value', 'source-missing');
      }
    });
  });

  // Pie Chart Logic
  function getPiePath(startAngle, endAngle) {
    const x1 = 100 + 90 * Math.cos(startAngle);
    const y1 = 100 + 90 * Math.sin(startAngle);
    const x2 = 100 + 90 * Math.cos(endAngle);
    const y2 = 100 + 90 * Math.sin(endAngle);
    const largeArc = endAngle - startAngle > Math.PI ? 1 : 0;
    return `M 100 100 L ${x1} ${y1} A 90 90 0 ${largeArc} 1 ${x2} ${y2} Z`;
  }

  function updatePie() {
    slicesGroup.innerHTML = '';

    const colors = ['var(--accent)', 'var(--warm)', 'var(--ink)'];
    const labels = ['命题 1', '命题 2', '命题 3'];

    let currentAngle = 0;
    const values = [credence.p1, credence.p2, credence.p3];

    values.forEach((val, index) => {
      if (val > 0.01) {
        const endAngle = currentAngle + 2 * Math.PI * val;
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        path.setAttribute('d', getPiePath(currentAngle, endAngle));
        path.setAttribute('fill', colors[index]);
        path.setAttribute('class', 'pie-slice');
        path.setAttribute('opacity', '0.8');
        slicesGroup.appendChild(path);
        currentAngle = endAngle;
      }
    });

    // Update status text
    if (isBalanced) {
      statusText.textContent = '理性均衡 (均分)';
      logicResult.textContent = '无排除分支';
      conclusionBox.classList.remove('hidden');
      feedbackEl.textContent = "当前为理性均衡状态。在缺乏特异性信息时，均匀分配置信度是明智的。";
      feedbackEl.className = 'feedback-msg success';
      feedbackEl.setAttribute('data-value', 'balanced');
    } else {
      statusText.textContent = '非均衡分配';
      let excludedText = excludedProps.length > 0 ? `排除：${excludedProps.join(', ')}` : '无明确排除';
      logicResult.textContent = excludedText;
      conclusionBox.classList.add('hidden');
      feedbackEl.textContent = "已应用特异性信息。注意：原文强调当前缺乏此类证据，此为教学演示。";
      feedbackEl.className = 'feedback-msg';
      feedbackEl.setAttribute('data-value', 'unbalanced');
    }
  }

  // Interaction
  applyBtn.addEventListener('click', () => {
    const val = inputEl.value.trim();
    if (!val) {
      feedbackEl.textContent = "请输入特异性信息。";
      feedbackEl.className = 'feedback-msg error';
      feedbackEl.setAttribute('data-value', 'empty-input');
      return;
    }

    // Teaching Example Logic based on text S061 (Meteor)
    if (val.includes('陨石') || val.includes('meteor') || val.includes('撞击')) {
      credence = { p1: 0.8, p2: 0.1, p3: 0.1 };
      excludedProps = ['命题 2', '命题 3'];
      isBalanced = false;
    } else if (val.includes('伦理') || val.includes('ethics') || val.includes('禁止')) {
      credence = { p1: 0.1, p2: 0.8, p3: 0.1 };
      excludedProps = ['命题 1', '命题 3'];
      isBalanced = false;
    } else if (val.includes('模拟') || val.includes('simulation') || val.includes('证据')) {
      credence = { p1: 0.1, p2: 0.1, p3: 0.8 };
      excludedProps = ['命题 1', '命题 2'];
      isBalanced = false;
    } else {
      // Default lock - no specific evidence found
      credence = { p1: 0.333, p2: 0.333, p3: 0.334 };
      excludedProps = [];
      isBalanced = true;
    }
    updatePie();
  });

  resetBtn.addEventListener('click', () => {
    inputEl.value = '';
    credence = { p1: 0.333, p2: 0.333, p3: 0.334 };
    excludedProps = [];
    isBalanced = true;
    updatePie();
    feedbackEl.textContent = "已复位至均匀分配状态。";
    feedbackEl.className = 'feedback-msg success';
    feedbackEl.setAttribute('data-value', 'reset');
  });

  // Init
  updatePie();

  // Keyboard accessibility for input
  inputEl.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      applyBtn.click();
    }
  });
})();
